#[test]
fn native_modal_power_normalization_and_static_physical_scattering() -> Result<(), &'static str> {
    for fixture in CASES {
        let line = PhysicalModalLine::from_native_modes(
            NativeModalCoefficients {
                voltage_basis: fixture.native_voltage,
                current_basis: fixture.native_current,
                characteristic_admittances: fixture.admittance,
                total_delays: fixture.delays,
                resistance: fixture.r,
                conductance: fixture.g,
                length: fixture.length,
            },
            WaveDiscretization {
                sections: 8,
                near_front: vec![0.; fixture.modes],
                far_front: vec![f64::INFINITY; fixture.modes],
                prune_histories: true,
            },
        )?;
        assert_eq!(line.modes(), fixture.modes);
        for (&actual, &expected) in line.modal_voltage_basis().iter().zip(fixture.expected_pv) {
            assert!(
                (actual - expected).abs() < 1e-10 * expected.abs().max(1.),
                "{} modal voltage normalization",
                fixture.name
            );
        }
        for (&actual, &expected) in line.modal_current_basis().iter().zip(fixture.expected_pi) {
            assert!(
                (actual - expected).abs() < 1e-10 * expected.abs().max(1.),
                "{} modal current normalization",
                fixture.name
            );
        }
        for (&actual, &expected) in line
            .network
            .static_scattering
            .iter()
            .zip(fixture.expected_s)
        {
            assert!(
                (actual - expected).abs() < 2e-9 * expected.abs().max(1.),
                "{} physical static scattering",
                fixture.name
            );
        }
    }
    Ok(())
}

#[test]
fn physical_conductor_solution_round_trips_into_accepted_modal_waves() -> Result<(), &'static str> {
    for fixture in CASES {
        let n = fixture.modes;
        let mut line = PhysicalModalLine::from_native_modes(
            NativeModalCoefficients {
                voltage_basis: fixture.native_voltage,
                current_basis: fixture.native_current,
                characteristic_admittances: fixture.admittance,
                total_delays: fixture.delays,
                resistance: fixture.r,
                conductance: fixture.g,
                length: fixture.length,
            },
            WaveDiscretization {
                sections: 8,
                near_front: vec![0.; n],
                far_front: vec![f64::INFINITY; n],
                prune_histories: true,
            },
        )?;
        let endpoint = fixture.delays[0] * 0.2;
        let ready = line.prepare(endpoint)?;
        assert!(ready.internal_steps() > 0);
        let mut injected = vec![0.; 2 * n];
        injected[0] = 0.7;
        let original = ready.prepared.evaluate(&injected[..n], &injected[n..])?;
        let emitted = [original.reflected_near(), original.transmitted_far()].concat();
        let mut physical_voltage = vec![0.; 2 * n];
        let mut physical_current = vec![0.; 2 * n];
        for side in 0..2 {
            for row in 0..n {
                let mut volts = 0.;
                let mut amps = 0.;
                for mode in 0..n {
                    let alpha = injected[side * n + mode] + emitted[side * n + mode];
                    let beta = injected[side * n + mode] - emitted[side * n + mode];
                    volts = line.modal_voltage_to_physical[row * n + mode].mul_add(alpha, volts);
                    amps = line.modal_current_to_physical[row * n + mode].mul_add(beta, amps);
                }
                physical_voltage[side * n + row] = volts;
                physical_current[side * n + row] = amps;
            }
        }
        let recovered = ready
            .equations
            .incident_from_physical(&physical_voltage, &physical_current)?;
        for (&actual, &expected) in recovered.iter().zip(&injected) {
            assert!(
                (actual - expected).abs() < 3e-10 * expected.abs().max(1.),
                "{} physical incident recovery",
                fixture.name
            );
        }
        let batch = ready.trial_physical(&physical_voltage, &physical_current)?;
        for (&actual, &expected) in batch
            .transmitted_far()
            .iter()
            .zip(original.transmitted_far())
        {
            assert!(
                (actual - expected).abs() < 3e-10,
                "{} recovered far wave",
                fixture.name
            );
        }
        let signals = (0..2 * n).map(Some).collect::<Vec<_>>();
        let returns = vec![None; 2 * n];
        let branches = (2 * n..4 * n).collect::<Vec<_>>();
        let stamped = ready.stamp(&signals, &returns, &branches)?;
        let values = [physical_voltage.clone(), physical_current.clone()].concat();
        let mut residual = vec![0.; 4 * n];
        for coeff in &stamped.coefficients {
            residual[coeff.row] = coeff
                .coefficient
                .mul_add(values[coeff.col], residual[coeff.row]);
        }
        for term in &stamped.rhs {
            residual[term.row] -= term.value;
        }
        for &value in &residual[2 * n..] {
            assert!(
                value.abs()
                    < 3e-8
                        * physical_voltage
                            .iter()
                            .map(|v| v.abs())
                            .fold(1.0_f64, f64::max),
                "{} physical MNA branch mismatch {}",
                fixture.name,
                value
            );
        }
        line.accept(batch)?;
        assert!(line.histories() >= 2 * (8 * 2 + 2));
    }
    Ok(())
}

#[test]
fn native_modal_rejects_nonphysical_scaled_admittance() {
    let fixture = &CASES[0];
    for bad_admittance in [f64::INFINITY, -1., f64::NAN] {
        let bad = [bad_admittance];
        let material = NativeModalCoefficients {
            voltage_basis: fixture.native_voltage,
            current_basis: fixture.native_current,
            characteristic_admittances: &bad,
            total_delays: fixture.delays,
            resistance: fixture.r,
            conductance: fixture.g,
            length: fixture.length,
        };
        assert!(
            PhysicalModalLine::from_native_modes(
                material,
                WaveDiscretization {
                    sections: 8,
                    near_front: vec![0.],
                    far_front: vec![f64::INFINITY],
                    prune_histories: true,
                }
            )
            .is_err()
        );
    }
    let material = NativeModalCoefficients {
        voltage_basis: fixture.native_voltage,
        current_basis: fixture.native_current,
        characteristic_admittances: fixture.admittance,
        total_delays: fixture.delays,
        resistance: fixture.r,
        conductance: fixture.g,
        length: -1.,
    };
    assert!(
        PhysicalModalLine::from_native_modes(
            material,
            WaveDiscretization {
                sections: 8,
                near_front: vec![0.],
                far_front: vec![f64::INFINITY],
                prune_histories: true,
            }
        )
        .is_err()
    );
}

#[test]
fn physical_eight_wire_dense_modal_event_schedule_is_finite() -> Result<(), &'static str> {
    let fixture = CASES
        .iter()
        .find(|f| f.modes == 8)
        .ok_or("missing physical eight-mode reference")?;
    for fraction in [0.2, 0.35, 0.5] {
        let line = PhysicalModalLine::from_native_modes(
            NativeModalCoefficients {
                voltage_basis: fixture.native_voltage,
                current_basis: fixture.native_current,
                characteristic_admittances: fixture.admittance,
                total_delays: fixture.delays,
                resistance: fixture.r,
                conductance: fixture.g,
                length: fixture.length,
            },
            WaveDiscretization {
                sections: 8,
                near_front: vec![0.; 8],
                far_front: vec![f64::INFINITY; 8],
                prune_histories: true,
            },
        )?;
        let start = std::time::Instant::now();
        let response = line.prepare(fixture.delays[0] * fraction)?;
        eprintln!(
            "physical 8-mode, 8 stages, fraction={fraction:.2}: events={}, duration={:?}",
            response.internal_steps(),
            start.elapsed()
        );
        assert!(
            response.internal_steps() < 100_000,
            "dense eight-mode exact event schedule needs compressed representation"
        );
    }
    Ok(())
}

#[test]
fn physical_eight_wire_exact_wavefront_crosstalk_and_accepted_energy() -> Result<(), &'static str> {
    let fixture = CASES
        .iter()
        .find(|f| f.modes == 8)
        .ok_or("missing physical eight-mode reference")?;
    let n = fixture.modes;
    let mut line = PhysicalModalLine::from_native_modes(
        NativeModalCoefficients {
            voltage_basis: fixture.native_voltage,
            current_basis: fixture.native_current,
            characteristic_admittances: fixture.admittance,
            total_delays: fixture.delays,
            resistance: fixture.r,
            conductance: fixture.g,
            length: fixture.length,
        },
        WaveDiscretization {
            sections: 8,
            near_front: vec![0.; n],
            far_front: vec![f64::INFINITY; n],
            prune_histories: true,
        },
    )?;
    let first_arrival = fixture.delays[0];
    let duration = first_arrival * 2.0;
    let far_quiet = vec![0.; n];
    let mut peak_crosstalk = 0.0_f64;
    let mut final_direct = 0.;
    for step in 1..=200_u32 {
        let time = duration * (f64::from(step) / 200.);
        let mut near = vec![0.; n];
        near[0] = (time / (0.2 * first_arrival)).min(1.);
        let trial = line.network.trial(time, &near, &far_quiet)?;
        if time < first_arrival {
            assert!(
                trial.transmitted_far().iter().all(|value| *value == 0.),
                "premature 8-wire wavefront at step {step}"
            );
        }
        peak_crosstalk = peak_crosstalk.max(
            trial.transmitted_far()[1..]
                .iter()
                .map(|value| value.abs())
                .fold(0.0_f64, f64::max),
        );
        final_direct = trial.transmitted_far()[0];
        line.network.accept(trial)?;
    }
    assert!(
        final_direct.abs() > 0.5,
        "physical 8-wire transmission missing"
    );
    assert!(
        peak_crosstalk > 1e-8,
        "physical mutual mode scattering missing"
    );
    let (input_energy, output_energy) = line.network.energies();
    assert!(output_energy <= input_energy);
    Ok(())
}
